import {
  NT_COMPLEX,
  NT_FLOAT,
  NT_INT,
  NT_RATIONAL,
  NT_AND,
  NT_OR,
  NT_WHILE,
  NT_WHILE_POST,
  NT_UNTIL,
  NT_UNTIL_POST,
  NT_RETURN,
  NT_BREAK,
  NT_NEXT,
  NT_REDO,
  NT_RETRY,
  NT_SUPER,
  NT_ZSUPER,
  NT_YIELD,
  NT_DEFINED_P,
  RbAst,
  VT_LIST,
  VT_SCALAR,
  V_NIL,
  vIdx,
  vMake,
  vTag,
} from "./ast";
import { RbBuilder, RbParseState } from "./builder";
import {
  RbContext,
  RbStaticEnv,
  SE_BLOCKARG_CURRENT,
  SE_BLOCKARG_INHERITED,
  SE_FORWARD_ARGS,
  SE_KWRESTARG_CURRENT,
  SE_KWRESTARG_INHERITED,
  SE_RESTARG_CURRENT,
  SE_RESTARG_INHERITED,
} from "./env";
import { RbLexer } from "./lexer";
import {
  RB_NIL,
  RL_LEX_EN_EXPR_BEG,
  RL_LEX_EN_EXPR_END,
  RL_LEX_EN_EXPR_ENDARG,
  RL_LEX_EN_EXPR_FNAME,
  RL_LEX_EN_EXPR_VALUE,
  RP_ACTION_CHECK,
  RP_ACTION_DEFAULT,
  RP_ACTION_POINTER,
  RP_ACTION_TABLE,
  RP_ACTION_TABLE_N,
  RP_GOTO_CHECK,
  RP_GOTO_DEFAULT,
  RP_GOTO_POINTER,
  RP_GOTO_TABLE,
  RP_GOTO_TABLE_N,
  RP_NT_BASE,
  RP_REDUCE_ACT,
  RP_REDUCE_LEN,
  RP_REDUCE_N,
  RP_REDUCE_NT,
  RP_SHIFT_N,
  TK_tLBRACE_ARG,
  TK_tLBRACK,
  TK_tLPAREN_ARG,
  TK_tNL,
  TK_tSTRING_DVAR,
  rbAt,
} from "./tables";

// Booleans the grammar keeps on the value stack (Context#in_kwarg).
const RB_TRUE: i32 = 16777242; // vMake(VT_SCALAR, (1 << 20) | 1)
const RB_FALSE: i32 = 16777226; // vMake(VT_SCALAR, 1 << 20)

export class RbParser {
  a: RbAst;
  b: RbBuilder;
  st: RbParseState;
  lx: RbLexer;
  ctx: RbContext;
  env: RbStaticEnv;
  lastTok: i32 = 0;
  failed: boolean = false;

  constructor(pts: i32[]) {
    this.a = new RbAst(pts);
    this.ctx = new RbContext();
    this.env = new RbStaticEnv();
    this.st = new RbParseState(this.env, this.ctx);
    this.b = new RbBuilder(this.a, this.st);
    this.lx = new RbLexer(pts, this.env, this.ctx);
    this.st.lineStarts.push(0);
    for (let i = 0; i < toI32(pts.length); i++) {
      if (pts[i] === 10) {
        this.st.lineStarts.push(i + 1);
      }
    }
  }

  /** The program's AST, or V_NIL; `failed` tells an empty program from a syntax error. */
  parse(): i32 {
    const states: i32[] = [0];
    const vals: i32[] = [];
    let readNext = true;
    let t = -1;
    let tokH = V_NIL;
    while (true) {
      if (this.failed || this.st.failed || this.lx.failed || this.lx.fatal) {
        this.failed = true;
        return V_NIL;
      }
      const s = states[states.length - 1];
      const ptr = rbAt(RP_ACTION_POINTER, s);
      let act = 0;
      if (ptr !== RB_NIL) {
        if (readNext) {
          if (t !== 0) {
            t = this.lx.advance();
            if (t === TK_tNL || t === TK_tSTRING_DVAR) {
              tokH = this.a.nilValueToken(this.lx.tokS, this.lx.tokE);
            } else {
              tokH = this.a.token(this.lx.tokVal, this.lx.tokS, this.lx.tokE);
            }
            this.lastTok = t;
          }
          readNext = false;
        }
        const i = ptr + t;
        act = i >= 0 && i < RP_ACTION_TABLE_N ? rbAt(RP_ACTION_TABLE, i) : RB_NIL;
        if (act === RB_NIL || rbAt(RP_ACTION_CHECK, i) !== s) {
          act = rbAt(RP_ACTION_DEFAULT, s);
        }
      } else {
        act = rbAt(RP_ACTION_DEFAULT, s);
      }
      if (act > 0 && act < RP_SHIFT_N) {
        vals.push(tokH);
        states.push(act);
        readNext = true;
      } else if (act < 0 && act > -RP_REDUCE_N) {
        const r = -act;
        const len = rbAt(RP_REDUCE_LEN, r);
        const nt = rbAt(RP_REDUCE_NT, r);
        const fn = rbAt(RP_REDUCE_ACT, r);
        const v: i32[] = [];
        const base = toI32(vals.length) - len;
        for (let j = 0; j < len; j++) {
          v.push(vals[base + j]);
        }
        for (let j = 0; j < len; j++) {
          vals.pop();
          states.pop();
        }
        let res = len > 0 ? v[0] : V_NIL;
        if (fn >= 0) {
          res = this.reduce(fn, v);
        } else if (fn === -2) {
          this.failed = true;
        }
        vals.push(res);
        const k1 = nt - RP_NT_BASE;
        const gp = rbAt(RP_GOTO_POINTER, k1);
        let next = RB_NIL;
        if (gp !== RB_NIL) {
          const gi = gp + states[states.length - 1];
          if (gi >= 0 && gi < RP_GOTO_TABLE_N) {
            const cs = rbAt(RP_GOTO_TABLE, gi);
            if (cs !== RB_NIL && rbAt(RP_GOTO_CHECK, gi) === k1) {
              next = cs;
            }
          }
        }
        if (next === RB_NIL) {
          next = rbAt(RP_GOTO_DEFAULT, k1);
        }
        states.push(next);
      } else if (act === RP_SHIFT_N) {
        return vals.length > 0 ? vals[0] : V_NIL;
      } else {
        this.failed = true;
        return V_NIL;
      }
    }
  }

  // ---- What the actions use -------------------------------------------------------

  /** diagnostic :error: the parse fails (RuboCop leaves the file alone). */
  fail(): i32 {
    this.failed = true;
    return V_NIL;
  }

  hb(b: boolean): i32 {
    return b ? RB_TRUE : RB_FALSE;
  }

  truthy(h: i32): boolean {
    return h !== V_NIL && h !== RB_FALSE;
  }

  /** A flag of a Context#dup kept on the value stack. */
  cb(h: i32, bit: i32): boolean {
    return (vIdx(h) & bit) !== 0;
  }

  /** An array literal; items whose bit is set in `splat` are lists spliced in. */
  ls(items: i32[], splat: i32): i32 {
    const l = this.a.list();
    for (let i = 0; i < toI32(items.length); i++) {
      if (i < 31 && (splat & (1 << i)) !== 0) {
        this.a.append(l, items[i]);
      } else {
        this.a.push(l, items[i]);
      }
    }
    return l;
  }

  localPush(): void {
    this.env.extendStatic();
    this.lx.cmdarg.push(false);
    this.lx.cond.push(false);
    this.st.npPush(true);
  }

  localPop(): void {
    this.env.unextend();
    this.lx.cmdarg.pop();
    this.lx.cond.pop();
    this.st.npPop();
  }

  endlessMethodName(nameT: i32): void {
    const n = this.a.tokValue(nameT);
    if (n !== "===" && n !== "==" && n !== "!=" && n !== "<=" && n !== ">=" && n.endsWith("=")) {
      this.fail();
    }
  }

  checkKwargName(nameT: i32): void {
    const n = this.a.tokValue(nameT);
    if (n.length > 0 && n.charCodeAt(0) >= 65 && n.charCodeAt(0) <= 90) {
      this.fail();
    }
  }

  extendStatic(): boolean {
    this.env.extendStatic();
    return true;
  }

  extendDynamic(): boolean {
    this.env.extendDynamic();
    return true;
  }

  unextend(): boolean {
    this.env.unextend();
    return true;
  }

  declareForwardArgs(): boolean {
    this.env.declare(SE_FORWARD_ARGS);
    return true;
  }

  declaredForwardArgsP(): boolean {
    return this.env.declared(SE_FORWARD_ARGS);
  }

  declareAnonymousBlockarg(): boolean {
    this.env.declare(SE_BLOCKARG_CURRENT);
    return true;
  }

  declaredAnonymousBlockargP(): boolean {
    return this.env.declared(SE_BLOCKARG_CURRENT) || this.env.declared(SE_BLOCKARG_INHERITED);
  }

  declaredAnonymousBlockargInCurrentScpeP(): boolean {
    return this.env.declared(SE_BLOCKARG_CURRENT);
  }

  parentHasAnonymousBlockargP(): boolean {
    return this.env.parentHas(SE_BLOCKARG_CURRENT);
  }

  declareAnonymousRestarg(): boolean {
    this.env.declare(SE_RESTARG_CURRENT);
    return true;
  }

  declaredAnonymousRestargP(): boolean {
    return this.env.declared(SE_RESTARG_CURRENT) || this.env.declared(SE_RESTARG_INHERITED);
  }

  declaredAnonymousRestargInCurrentScopeP(): boolean {
    return this.env.declared(SE_RESTARG_CURRENT);
  }

  parentHasAnonymousRestargP(): boolean {
    return this.env.parentHas(SE_RESTARG_CURRENT);
  }

  declareAnonymousKwrestarg(): boolean {
    this.env.declare(SE_KWRESTARG_CURRENT);
    return true;
  }

  declaredAnonymousKwrestargP(): boolean {
    return this.env.declared(SE_KWRESTARG_CURRENT) || this.env.declared(SE_KWRESTARG_INHERITED);
  }

  declaredAnonymousKwrestargInCurrentScopeP(): boolean {
    return this.env.declared(SE_KWRESTARG_CURRENT);
  }

  parentHasAnonymousKwrestargP(): boolean {
    return this.env.parentHas(SE_KWRESTARG_CURRENT);
  }

  // ---- The reduce actions ---------------------------------------------------------

  reduce(n: i32, v: i32[]): i32 {
    switch (n) {
      // @CASES@
      default:
        return v.length > 0 ? v[0] : V_NIL;
    }
  }

  // @ACTIONS@
}
